import React, {useMemo} from 'react';

import type {Field} from '@weavix/tracker-api-types';

import type {FieldsSelectProps} from '~/src/components/FieldsSelect';
import {FieldsSelect} from '~/src/components/FieldsSelect';
import type {
    TrackerSelectGroup,
    TrackerSelectItem,
    TrackerSelectItemValueBase,
    TrackerSelectItems,
} from '~/src/components/TrackerSelect';

export type PluginFieldsSelectField = {
    id: string;
    name: string;
    category: TrackerSelectItemValueBase;
} & Partial<Omit<Field, 'category' | 'name'>>;

export type PluginFieldsSelectProps = {
    fields: PluginFieldsSelectField[];
} & Omit<FieldsSelectProps, 'groups'>;

export const PluginFieldsSelect = ({fields, ...fieldsSelectProps}: PluginFieldsSelectProps) => {
    const groups = useMemo(() => {
        const categories: Record<string, TrackerSelectGroup> = {};
        if (fields && fields.length > 0) {
            fields.forEach((field) => {
                const categoryId = String(field.category?.id);
                if (field.category?.id) {
                    categories[categoryId] = categories[categoryId] || {
                        ...field.category,
                        name: field.category?.display,
                        collapsible: true,
                        items: {} as TrackerSelectItems,
                    };
                    categories[categoryId].items[field.id] = {
                        ...field,
                        display: String(field.name),
                    } as unknown as TrackerSelectItem;
                }
            });
        }
        return Object.values(categories);
    }, [fields]);

    return <FieldsSelect groups={groups} {...fieldsSelectProps} />;
};
